inline const char *taskJsonForRobotCount(int num_robots) {
    switch (num_robots) {
    case 2:
        return kTasks2;
    case 4:
        return kTasks4;
    case 8:
        return kTasks8;
    case 16:
        return kTasks16;
    default:
        throw std::runtime_error("Panda cage built-in tasks support robot counts 2, 4, 8, and 16");
    }
}

